{"hypotheses": [
  {
    "name": "Organizational Intangibles Efficiency",
    "mechanism": "Firms efficiently converting organizational capital and brand investment into sales growth signal superior management and competitive positioning, which is not captured by looking at each input alone. Firms with strong organizational capital and brand investment, but only when this coincides with above-median sales-over-inventory growth, should outperform.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "GrSaleToGrInv"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "GrSaleToGrInv", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Option Sentiment Supply Shock",
    "mechanism": "Stocks that experience a simultaneous rise in call option volume and a steepening of the volatility smile may reflect shifts in investor sentiment, only profitable when combined. This suggests supply/demand imbalances in the derivatives market that spill over to the underlying, independent from volume or volatility alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "dVolCall"},
        {"weight": 0.5, "primitive": "SmileSlope"},
        {"weight": -0.5, "primitive": "OptionVolume1"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "OptionVolume1", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Supply Chain Cross-Momentum",
    "mechanism": "Firms that enjoy simultaneous positive momentum among both their key customers and suppliers are positioned at the intersection of strong demand and robust supply channels. This amplifies their own prospects beyond what is inferred from customer or supplier momentum in isolation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "iomom_supp"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Earnings-Surprise-Linked Short Interest",
    "mechanism": "High short interest combined with recent positive earnings surprises can signal overreaction by short sellers who ignore new information. Stocks with both characteristics are prone to short covering and positive drift, but only when the term spread is positive (accommodative credit conditions).",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShortInterest"},
        {"weight": 1.0, "primitive": "EarningsSurprise"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Governance-Driven Capital Reallocation",
    "mechanism": "Firms with high governance scores and recent increases in payout yield (dividends or buybacks) are likely reallocating capital efficiently. The combination indicates both willingness and ability to return capital, which predicts future outperformance versus governance or payout policies alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 1.0, "primitive": "PayoutYield"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "PayoutYield", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Analyst Dispersion and Deferred Revenue Growth",
    "mechanism": "Stocks with high analyst forecast dispersion but rising deferred revenue may be underappreciated: uncertainty exists, but growing deferred revenue signals robust underlying demand. This blend identifies stocks with misunderstood but improving prospects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "DelDRC"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Cash Productivity and Franchise Investment",
    "mechanism": "Firms with high cash productivity that are also increasing excluded expenses (often related to franchise or intangible investments) are reinvesting operational cash into future growth. This combination signals both operational excellence and forward-looking franchise building.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": 0.5, "primitive": "ExclExp"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "ExclExp", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Debt-Equity Contrarian Spread",
    "mechanism": "Companies simultaneously increasing both debt and equity financing are typically shunned by traditional factor models, but in periods of negative market momentum these actions may reflect opportunistic capital structure optimization. The joint signal exploits contrarian rebalancing ignored by most investors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetDebtFinance"},
        {"weight": 1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 20
  }
]}
